    p = 0
    mp = []
    mm = []
    for _ in range(N):
        w = INF
        e = 0
        for s in sys.stdin.readline().rstrip():
            if s == '(': e += 1
            else: e -= 1
            w = min(w,e)
        if w < 0:
            if e > 0 :mp.append((w,e))
            else: mm.append((w,e))
        else: p += e

    mp.sort(reverse=True)
    for w,e in mp:
        if p + w < 0:
            print('No')
            exit(0)
        p += e
    min_p = p
    mm.sort(reverse=True)
    if mm:
        min_p += mm[0][0]
        p += mm[0][1]
        if p < 0 or min_p < 0:
