    N = int(input())
    S = [input() for _ in range(N)]
    L1 = []
    L2 = []
    for i in range(N):
        t = 0
        mint = 0
        for s in S[i]:
            if s == "(":
                t += 1
            else:
                t -= 1
            mint = min(mint, t)
        if t >= 0:
            L1.append((t, mint))
        else:
            t = 0
            mint = 0
            for j in range(len(S[i]) - 1, -1, -1):
                if S[i][j] == ")":
                    t += 1
                else:
                    t -= 1
                mint = min(mint, t)
            L2.append((t, mint))

