    m, s = heappop(zero)
    if num + m < 0:
        print('No')
        exit()
while neg:
    m, s = heappop(neg)
    if num + m < 0:
        print('No')
        exit()
    num -= s
if num == 0:
    print('Yes')
else:
    print('No')

