def I():
    return int(sys.stdin.buffer.readline())

def S():
    return sys.stdin.buffer.readline().rstrip().decode()

def solve():
    n = I()
    sp = []
    sm = []

    for _ in range(n):
        s = S()
        p = 0
        m = 0
        for ch in s:
            if ch == '(':
                p += 1
            else:
                p -= 1
            if p < m:
                m = p
        if p > 0:
            sp.append((m, p))
        else:
