import sys
from heapq import heappush, heappop

input = sys.stdin.readline

n = int(input())
pos = []
zero = []
neg = []

for _ in range(n):
    s = input().strip()
    cur = 0
    mn = 0
    for ch in s:
        if ch == '(':
            cur += 1
        else:
            cur -= 1
            if cur < mn:
                mn = cur

    if cur > 0:
        heappush(pos, (-mn, cur))
    elif cur == 0:
        heappush(zero, (mn, cur))
    else:
        heappush(neg, (mn - cur, cur))

num = 0

while pos:
    m, s = heappop(pos)
    if num - m < 0:
        print("No")
        sys.exit()
    num += s

while zero:
    m, s = heappop(zero)
    if num + m < 0:
        print("No")
        sys.exit()

while neg:
    m, s = heappop(neg)
    m += s
    if num + m < 0:
        print("No")
        sys.exit()
    num += s

print("Yes" if num == 0 else "No")

