import sys

input = sys.stdin.readline

def count(s):
    e = 0
    m = 0
    for ch in s:
        if ch == '(':
            e += 1
        else:
            e -= 1
            if e < m:
                m = e
    return e, m

def count_reverse(s):
    e = 0
    m = 0
    for ch in reversed(s):
        if ch == ')':
            e += 1
        else:
            e -= 1
            if e < m:
                m = e
    return e, m

def main():
    n = int(input())
    S = [input().strip() for _ in range(n)]

    P = []
    M = []
    Z = [0]

    for s in S:
        e, m = count(s)
        if e > 0:
            P.append((m, e))
        elif e < 0:
            e2, m2 = count_reverse(s)
            M.append((m2, e2))
        else:
            Z.append(m)

    P.sort(reverse=True)
    M.sort(reverse=True)

    sp = 0
    sm = 0

    for m, e in P:
        if sp + m < 0:
            print("No")
            return
        sp += e

    for m, e in M:
        if sm + m < 0:
            print("No")
            return
        sm += e

    if sp == sm and sp + min(Z) >= 0:
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    main()

