#!/usr/bin/python3
import sys

def main():
    input = sys.stdin.readline
    n = int(input())
    left = []
    right = []

    for _ in range(n):
        s = input().strip()
        l = r = 0
        for ch in s:
            if ch == '(':
                l += 1
            else:
                if l > 0:
                    l -= 1
                else:
                    r += 1

        if l - r >= 0:
            left.append((r, l))
        else:
            right.append((r, l))

    left.sort(key=lambda t: t[0])
    right.sort(key=lambda t: t[1], reverse=True)

    bal = 0
    for r, l in left + right:
        bal -= r
        if bal < 0:
            print("No")
            return
        bal += l

    print("Yes" if bal == 0 else "No")

if __name__ == "__main__":
    main()

