import sys

readline = sys.stdin.readline

def check(arr):
    h = 0
    for bx, hx in arr:
        if h + bx < 0:
            return False
        h += hx
    return True

def main():
    n = int(readline())
    ls = []
    rs = []
    tot = 0
    bm = 0

    for _ in range(n):
        si = readline().strip()
        b = 0
        h = 0
        for c in si:
            if c == '(':
                h += 1
            else:
                h -= 1
            if h < b:
                b = h

        if h == 0 and b != 0:
            if b < bm:
                bm = b
        elif h > 0:
            ls.append((b, h))
        else:
            rs.append((b - h, -h))
        tot += h

    ls.append((bm, 0))

    if tot != 0:
        print('No')
        return

    ls.sort(reverse=True)
    rs.sort(reverse=True)

    if check(ls) and check(rs):
        print('Yes')
    else:
        print('No')

if __name__ == "__main__":
    main()

