    s = input().strip()
    a = 0  # unmatched '('
    b = 0  # unmatched ')' when scanning left to right
    for c in s:
        if c == "(":
            a += 1
        else:
            if a > 0:
                a -= 1
            else:
                b += 1
    if a >= b:
