def input():
    return sys.stdin.readline().strip()


def solve():
    N = int(input())
    chunks = []

    for _ in range(N):
        s = input()
        l = r = 0
        for c in s:
            if c == '(':
                r += 1
            else:
                if r > 0:
                    r -= 1
                else:
                    l += 1
        if l != 0 or r != 0:
            chunks.append((l, r))

    up = []
    down = []
    for l, r in chunks:
        if l <= r:
            up.append((l, r))
        else:
            down.append((l, r))

    up.sort(key=itemgetter(0))
    down.sort(key=itemgetter(1), reverse=True)

    cur = 0
    for l, r in up + down:
        if l > cur:
            return 'No'
        cur += r - l

    return 'Yes' if cur == 0 else 'No'


print(solve())

