# -*- coding: utf-8 -*-
import sys

buff_readline = sys.stdin.buffer.readline


def read_int():
    return int(buff_readline())


def read_str():
    return buff_readline().strip().decode()


def slv(N, S):
    A = []
    B = []

    for s in S:
        tmp = []
        for c in s:
            if c == '(':
                tmp.append(c)
            else:
                if tmp and tmp[-1] == '(':
                    tmp.pop()
                else:
                    tmp.append(c)

        l = tmp.count('(')
        r = len(tmp) - l

        if r - l <= 0:
            A.append((l, r))
        else:
            B.append((l, r))

    A.sort(key=lambda x: x[1])
    B.sort(key=lambda x: x[0], reverse=True)

    cur = 0
    for l, r in A:
        cur += r
        if cur > 0:
            return 'No'
        cur -= l

    for l, r in B:
        cur += r
        if cur > 0:
            return 'No'
        cur -= l

    return 'Yes' if cur == 0 else 'No'


def main():
    N = read_int()
    S = [read_str() for _ in range(N)]
    print(slv(N, S))


if __name__ == '__main__':
    main()

