import sys

def main():
    input = sys.stdin.readline
    n = int(input())
    ss = [input().strip() for _ in range(n)]

    left = right = rev_l = rev_r = 0
    min_revr = 10**20
    min_revl = 10**20

    for S in ss:
        stack = []
        l = r = 0
        for s in S:
            if s == '(':
                if stack:
                    if stack[-1] == ')':
                        stack.append('(')
                        l = 1
                    else:
                        stack.append('(')
                        l += 1
                else:
                    stack.append('(')
                    l = 1
            else:
                if stack:
                    if stack[-1] == '(':
                        stack.pop()
                        l -= 1
                    else:
                        stack.append(')')
                        r += 1
                else:
                    stack.append(')')
                    r = 1

        if l == 0:
            right += r
        elif r == 0:
            left += l
        else:
            rev_r += r
            rev_l += l
            if r < min_revr:
                min_revr = r
            if l < min_revl:
                min_revl = l

    if min_revr == 10**20:
        min_revr = 0
    if min_revl == 10**20:
        min_revl = 0

    if left + rev_l == rev_r + right and left >= min_revr and right >= min_revl:
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    main()

