patch:
import sys

def main():
    input = sys.stdin.readline
    N = int(input())

    up = []    # total > 0
    down = []  # total <= 0

    for _ in range(N):
        s = input().strip()
        h = 0
        mn = 0
        for c in s:
            if c == '(':
                h += 1
            else:
                h -= 1
                if h < mn:
                    mn = h

        if h > 0:
            up.append((mn, h))
        else:
            down.append((mn, h))

    # For positive-total strings: sort by larger minimum prefix first
    up.sort(key=lambda x: (x[0], x[1]), reverse=True)

    cur = 0
    for mn, h in up:
        if cur + mn < 0:
            print("No")
            return
        cur += h

    # For non-positive-total strings: sort by (h - mn) ascending
    # Equivalent to the reference solution's ordering for the "down" part.
    down.sort(key=lambda x: (x[1] - x[0], x[0]), reverse=True)

    for mn, h in down:
        if cur + mn < 0:
            print("No")
            return
        cur += h

    print("Yes" if cur == 0 else "No")

if __name__ == "__main__":
    main()

