import sys

def main():
    input = sys.stdin.readline
    n = int(input())

    left = []
    mid = []
    midminus = []
    total_l = 0
    total_r = 0

    for _ in range(n):
        s = input().strip()
        l = 0
        r = 0
        for c in s:
            if c == '(':
                l += 1
            else:
                if l > 0:
                    l -= 1
                else:
                    r += 1

        total_l += l
        total_r += r

        if l > 0 and r == 0:
            left.append((l, r))
        elif l > 0 and r > 0:
            if l > r:
                mid.append((r, l))
            else:
                midminus.append((r, l))
        elif l == 0 and r > 0:
            # These strings must be placed before others
            left.append((l, r))

    if total_l != total_r:
        print("No")
        return

    A = 0
    for l, r in left:
        A += l

    mid.sort(key=lambda x: (x[0], -x[1]))
    midminus.sort(key=lambda x: x[0] - x[1])
    mid.extend(midminus)

    cur = A
    for a, b in mid:
        if cur < a:
            print("No")
            return
        cur -= a
        cur += b

    print("Yes")

