import sys

def I():
    return int(sys.stdin.buffer.readline())

def S():
    return sys.stdin.buffer.readline().rstrip().decode()

def solve():
    n = I()
    sp = []
    sm = []

    for _ in range(n):
        s = S()
        p = 0
        m = 0
        for ch in s:
            if ch == '(':
                p += 1
            else:
                p -= 1
            if p < m:
                m = p
        if p > 0:
            sp.append((m, p))
        else:
            sm.append((m, p))

    sp.sort(reverse=True)
    sm.sort(key=lambda x: x[0] - x[1])

    k = 0
    for m, p in sp:
        if k + m < 0:
            print("No")
            return
        k += p

    for m, p in sm:
        if k + m < 0:
            print("No")
            return
        k += p

    print("Yes" if k == 0 else "No")

if __name__ == "__main__":
    solve()

