import sys

def main():
    input = sys.stdin.readline
    n = int(input())
    L_cnt = []
    R_cnt = []
    LR_cnt = []

    for _ in range(n):
        s = input().strip()
        bal = 0
        min_pref = 0
        for c in s:
            if c == '(':
                bal += 1
            else:
                bal -= 1
            if bal < min_pref:
                min_pref = bal

        if bal > 0 and min_pref >= 0:
            L_cnt.append(bal)
        elif bal < 0 and min_pref == bal:
            R_cnt.append(-bal)
        elif bal == 0 and min_pref >= 0:
            continue
        else:
            # General case: store as (needed_left, extra_right)
            # needed_left = maximum deficit before the string can be safely placed
            # extra_right = net surplus of ')' after matching as much as possible
            # We derive these by scanning similarly to the reference logic.
            l = 0
            r = 0
            flag = 0
            for c in s:
                if not flag and c == ')':
                    r += 1
                elif c == '(':
                    flag = 1
                    l += 1
                else:
                    l -= 1
                    if l == 0:
                        flag = 0
            if r == 0 and l == 0:
                continue
            if r == 0:
                L_cnt.append(l)
            elif l == 0:
                R_cnt.append(r)
            else:
                LR_cnt.append((l, r))

    L = sum(L_cnt)
    R = sum(R_cnt)

    if not LR_cnt:
        print("Yes" if L == R else "No")
        return

    if not L_cnt or not R_cnt:
        print("No")
        return

    box1 = []
    box2 = []
    for l, r in LR_cnt:
        if L >= r and r <= l:
            L += l - r
        elif r <= l:
            box1.append((l, r))
        else:
            box2.append((l, r))

    for l, r in box1:
        L -= r
        if L < 0:
            print("No")
            return
        L += l

    for l, r in box2:
        L -= r
        if L < 0:
            print("No")
            return
        L += l

    print("Yes" if L == R else "No")

if __name__ == "__main__":
    main()

