import sys

def main():
    input = sys.stdin.readline
    N = int(input())
    A = []
    B = []

    for _ in range(N):
        S = input().strip()
        cur = 0
        tmp = []
        for ch in S:
            if ch == '(':
                tmp.append(ch)
            else:
                if tmp and tmp[-1] == '(':
                    tmp.pop()
                else:
                    tmp.append(ch)

        l = tmp.count('(')
        r = len(tmp) - l

        if r - l <= 0:
            A.append((l, r))
