import sys

def main():
    input = sys.stdin.readline
    N = int(input())

    pos = []
    neg = []
    total = 0

    for _ in range(N):
        s = input().strip()
        bal = 0
        mn = 0
        for c in s:
            if c == '(':
                bal += 1
            else:
                bal -= 1
            if bal < mn:
                mn = bal

        total += bal
        if bal >= 0:
            pos.append((mn, bal))
        else:
            neg.append((mn - bal, -bal))  # transformed for right-to-left processing

    if total != 0:
        print("No")
        return

    pos.sort(key=lambda x: (x[0], x[1]), reverse=True)
    cur = 0
    for mn, bal in pos:
        if cur + mn < 0:
            print("No")
            return
        cur += bal

    neg.sort(key=lambda x: (x[0], x[1]), reverse=True)
    cur = 0
    for mn, bal in neg:
        if cur + mn < 0:
            print("No")
            return
        cur += bal

    print("Yes")

if __name__ == "__main__":
    main()

