import sys

input = sys.stdin.readline

N = int(input())
left = []
mid = []
midminus = []
right = []
L = []
R = []

for _ in range(N):
    s = input().strip()
    l = 0
    r = 0
    for x in s:
        if x == '(':
            l += 1
        else:
            if l > 0:
                l -= 1
            else:
                r += 1

    if l > 0 and r == 0:
        left.append((l, r))
    elif l > 0 and r > 0:
        if l > r:
            mid.append((r, l))
        else:
            midminus.append((r, l))
    elif l == 0 and r > 0:
        right.append((l, r))

    L.append(l)
    R.append(r)

if sum(L) != sum(R):
    print('No')
    sys.exit()

A = 0
for x in left:
    A += x[0]

mid = sorted(mid, key=lambda x: (x[0], -x[1]))
midminus = sorted(midminus, key=lambda x: x[0] - x[1])
mid += midminus

l = A
for a, b in mid:
    if l < a:
        print('No')
        sys.exit()
    l -= a
    l += b

print('Yes')

