import sys

input = sys.stdin.readline


def parse(s):
    bottom = 0
    delta = 0
    for c in s.strip():
        delta += 1 if c == "(" else -1
        if delta < bottom:
            bottom = delta
    return bottom, delta


def compute(pars):
    pars.sort(reverse=True)
    h = 0
    for bottom, delta in pars:
        if h + bottom < 0:
            return None
        h += delta
    return h


def solve():
    N = int(input())
    incs = []
    decs = []

    for _ in range(N):
        bottom, delta = parse(input())
        if delta > 0:
            incs.append((bottom, delta))
        else:
            decs.append((bottom - delta, -delta))

    inc_tot = compute(incs)
    if inc_tot is None:
        return False

    dec_tot = compute(decs)
    if dec_tot is None:
        return False

    return inc_tot == dec_tot


def main():
    print("Yes" if solve() else "No")


if __name__ == "__main__":
    main()

