# coding: utf-8
import sys

sr = lambda: sys.stdin.readline().rstrip()
ir = lambda: int(sr())

def resolve():
    N = ir()
    pos = []
    neg = []
    tot = 0

    for _ in range(N):
        s = sr()
        tmp = 0
        b = 0
        for c in s:
            if c == '(':
                tmp += 1
            else:
                tmp -= 1
                if tmp < b:
                    b = tmp
        if tmp > 0:
            pos.append((b, tmp))
        else:
            neg.append((b - tmp, -tmp))
        tot += tmp

    if tot != 0:
        print('No')
        return

    pos.sort(reverse=True)
    neg.sort(reverse=True)

    c = 0
    for b, t in pos:
        if c + b < 0:
            print('No')
            return
        c += t

    c = 0
    for b, t in neg:
        if c + b < 0:
            print('No')
            return
        c += t

    print('Yes')

if __name__ == "__main__":
    resolve()

import sys

def main():
    input = sys.stdin.readline
    N = int(input())

    plus_seqs = []
    minus_seqs = []

    for _ in range(N):
        s = input().strip()
        h = 0
        min_h = 0
        for ch in s:
            if ch == '(':
                h += 1
            else:
                h -= 1
            if h < min_h:
                min_h = h

        if h >= 0:
            plus_seqs.append((min_h, h))
        else:
            minus_seqs.append((min_h - h, -h))

    plus_seqs.sort()
    minus_seqs.sort()

    height = 0
    for min_h, h in reversed(plus_seqs):
        if height + min_h < 0:
            print("No")
            return
        height += h

    height2 = 0
    for min_h, h in reversed(minus_seqs):
        if height2 + min_h < 0:
            print("No")
            return
        height2 += h

    print("Yes" if height == height2 else "No")

if __name__ == "__main__":
    main()

