import sys

def main():
    input = sys.stdin.readline
    n = int(input())
    pos = []
    neg = []
    total = 0
    min_zero = 0

    for _ in range(n):
        t = input().strip()
        h = 0
        mn = 0
        for ch in t:
            if ch == '(':
                h += 1
            else:
                h -= 1
            if h < mn:
                mn = h

        total += h
        if h > 0:
            pos.append((mn, h))
        elif h < 0:
            neg.append((mn - h, -h))
        else:
            if mn != 0:
                min_zero = min(min_zero, mn)

    if total != 0:
        print("No")
        return

    pos.append((min_zero, 0))

    pos.sort(key=lambda x: x[0], reverse=True)
    cur = 0
    for mn, h in pos:
        if cur + mn < 0:
            print("No")
            return
        cur += h

    neg.sort(key=lambda x: x[0], reverse=True)
    cur = 0
    for mn, h in neg:
        if cur + mn < 0:
            print("No")
            return
        cur += h

    print("Yes")

if __name__ == "__main__":
    main()

