import sys

def main():
    input = sys.stdin.readline
    N = int(input())

    P = []  # strings with positive total balance
    M = []  # strings with negative total balance (stored reversed)
    Z = [0]  # strings with zero total balance: store minimum prefix balance

    for _ in range(N):
        s = input().strip()
        e = 0
        m = 0
        for ch in s:
            if ch == '(':
                e += 1
            else:
                e -= 1
                if e < m:
                    m = e

        if e > 0:
            P.append((m, e))
        elif e < 0:
            # analyze reversed string
            e2 = 0
            m2 = 0
            for ch in reversed(s):
                if ch == ')':
                    e2 += 1
                else:
                    e2 -= 1
                    if e2 < m2:
                        m2 = e2
            M.append((m2, e2))
        else:
            Z.append(m)

    P.sort(reverse=True)
    M.sort(reverse=True)

    sp = 0
    sm = 0

    for m, e in P:
        if sp + m < 0:
            print("No")
            return
        sp += e

    for m, e in M:
        if sm + m < 0:
            print("No")
            return
        sm += e

    if sp == sm and sp + min(Z) >= 0:
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    main()

