import sys

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n = int(data[0])
    strings = data[1:]

    left = []
    mid = []
    midminus = []
    total_l = 0
    total_r = 0

    for s in strings:
        l = 0
        r = 0
        for ch in s.decode():
            if ch == '(':
                l += 1
            else:
                if l > 0:
                    l -= 1
                else:
                    r += 1

        total_l += l
        total_r += r

        if l > 0 and r == 0:
            left.append((l, r))
        elif l > 0 and r > 0:
            if l > r:
                mid.append((r, l))
            else:
                midminus.append((r, l))
        elif l == 0 and r > 0:
            pass

    if total_l != total_r:
        print("No")
        return

    A = 0
    for x, _ in left:
        A += x

    mid.sort(key=lambda x: (x[0], -x[1]))
    midminus.sort(key=lambda x: x[0] - x[1])
    mid.extend(midminus)

    l = A
    for a, b in mid:
        if l < a:
            print("No")
            return
        l -= a
        l += b

    print("Yes")

if __name__ == "__main__":
    main()

