import sys
from operator import itemgetter


def input():
    return sys.stdin.readline().strip()


def parse(s):
    l = r = 0
    for c in s:
        if c == '(':
            r += 1
        else:
            if r > 0:
                r -= 1
            else:
                l += 1
    return l, r


def solve():
    N = int(input())
    chunks = [parse(input()) for _ in range(N)]
    chunks = [x for x in chunks if x != (0, 0)]

    up = []
    down = []
    for l, r in chunks:
        if l <= r:
            up.append((l, r))
        else:
            down.append((l, r))

    up.sort(key=itemgetter(0))
    down.sort(key=itemgetter(1), reverse=True)

    balance = 0
    for l, r in up + down:
        if l > balance:
            return 'No'
        balance += r - l

    return 'Yes' if balance == 0 else 'No'


print(solve())

