import sys

def input():
    return sys.stdin.readline().strip()

def main():
    n = int(input())
    A = []
    B = []

    for _ in range(n):
        s = input()
        tmp = []
        for ch in s:
            if ch == '(':
                tmp.append(ch)
            else:
                if tmp and tmp[-1] == '(':
                    tmp.pop()
                else:
                    tmp.append(ch)

        l = tmp.count('(')
        r = len(tmp) - l

        if r - l <= 0:
            A.append((l, r))
        else:
            B.append((l, r))

