import sys

def main():
    input = sys.stdin.readline
    N = int(input())
    S = [input().strip() for _ in range(N)]

    L1 = []
    L2 = []

    for s in S:
        t = 0
        mint = 0
        for ch in s:
            if ch == "(":
                t += 1
            else:
                t -= 1
            if t < mint:
                mint = t

        if t >= 0:
            L1.append((t, mint))
        else:
            t = 0
            mint = 0
            for ch in reversed(s):
                if ch == ")":
                    t += 1
                else:
                    t -= 1
                if t < mint:
                    mint = t
            L2.append((t, mint))

