#!/usr/bin/env python
# -*- coding: utf-8 -*-

import sys


def main():
    input = sys.stdin.readline
    N = int(input())

    pos = []
    neg = []
    total = 0

    for _ in range(N):
        s = input().strip()
        bal = 0
        min_pref = 0
        for c in s:
            if c == '(':
                bal += 1
            else:
                bal -= 1
            if bal < min_pref:
                min_pref = bal

        total += bal

        if bal >= 0:
            pos.append((min_pref, bal))
        else:
            neg.append((min_pref - bal, bal))  # transformed for reverse processing

    if total != 0:
        print('No')
        return

    # Strings with non-negative balance: sort by decreasing minimum prefix requirement
    pos.sort(key=lambda x: x[0], reverse=True)

    cur = 0
    for mn, bal in pos:
        if cur + mn < 0:
            print('No')
            return
        cur += bal

    # Strings with negative balance: process from the end, equivalent to reversed strings
    neg.sort(key=lambda x: x[0], reverse=True)

    cur = 0
    for mn, bal in neg:
        if cur + mn < 0:
            print('No')
            return
        cur += -bal

    print('Yes')


if __name__ == '__main__':
    main()

