import sys

def main():
    input = sys.stdin.readline
    N = int(input())
    S_list = [input().strip() for _ in range(N)]

    min_revr, min_revl = 10**20, 10**20
    left, rev_l, rev_r, right = 0, 0, 0, 0

    for S in S_list:
        stack = []
        l, r = 0, 0
        for s in S:
            if s == '(':
                if stack:
                    if stack[-1] == ')':
                        stack.append('(')
                        l = 1
                    else:
                        stack.append('(')
                        l += 1
                else:
