import sys

def main():
    input = sys.stdin.readline
    N = int(input())
    S = [input().strip() for _ in range(N)]

    def count(s):
        n1 = 0  # unmatched ')'
        n2 = 0  # unmatched '('
        for ch in s:
            if ch == '(':
                n2 += 1
            else:
                if n2 > 0:
                    n2 -= 1
                else:
                    n1 += 1
        return n1, n2

    l1 = []
    l2 = []
    m1 = 0
    m2 = 0

    for s in S:
        n1, n2 = count(s)
        if n1 + n2 == 0:
            continue
        if n1 == 0:
            m1 += n2
        elif n2 == 0:
            m2 += n1
        elif n2 - n1 >= 0:
            l1.append((n1, n2))
        else:
            l2.append((n1, n2))

    ans = 'Yes'

    l1.sort()
    for n1, n2 in l1:
        if m1 < n1:
            ans = 'No'
            break
        m1 += n2 - n1

    l2.sort(key=lambda x: x[1])
    for n1, n2 in l2:
        if m2 < n2:
            ans = 'No'
            break
        m2 += n1 - n2

    if m1 != m2:
        ans = 'No'

    print(ans)

if __name__ == "__main__":
    main()

