import sys
from operator import itemgetter

readline = sys.stdin.buffer.readline


def parse(s):
    l = r = 0
    for c in s:
        if c == ord('('):
            r += 1
        else:
            if r > 0:
                r -= 1
            else:
                l += 1
    return l, r


def main():
    n = int(readline())
    p = []
    for _ in range(n):
        s = readline().strip()
        lr = parse(s)
        if lr != (0, 0):
            p.append(lr)

    u = []
    d = []
    for l, r in p:
        if l <= r:
            u.append((l, r))
        else:
            d.append((l, r))

    u.sort(key=itemgetter(0))
    d.sort(key=itemgetter(1), reverse=True)

    cur = 0
    for ll, rr in u + d:
        if ll > cur:
            print("No")
            return
        cur += rr - ll

    print("Yes" if cur == 0 else "No")


if __name__ == "__main__":
    main()

