import sys

def main():
    input = sys.stdin.readline
    n = int(input())
    L_cnt = []
    R_cnt = []
    LR_cnt = []

    for _ in range(n):
        s = input().strip()
        bal = 0
        min_pref = 0
        for c in s:
            if c == '(':
                bal += 1
            else:
                bal -= 1
            if bal < min_pref:
                min_pref = bal

        if bal > 0 and min_pref >= 0:
            L_cnt.append(bal)
        elif bal < 0 and min_pref == bal:
            R_cnt.append(-bal)
        elif bal == 0 and min_pref >= 0:
            continue
        else:
            # General case: store as (need_before, surplus_after)
            need = -min_pref
            surplus = bal + need
            LR_cnt.append((need, surplus))

    L = sum(L_cnt)
    R = sum(R_cnt)

    if not LR_cnt:
        print("Yes" if L == R else "No")
        return

    if not L_cnt or not R_cnt:
        print("No")
        return

    box1 = []
    box2 = []
    for need, surplus in LR_cnt:
        if L >= need and need <= surplus:
            L += surplus - need
        elif need <= surplus:
            box1.append((need, surplus))
        else:
            box2.append((need, surplus))

    for need, surplus in box1:
        L -= need
        if L < 0:
            print("No")
            return
        L += surplus

    for need, surplus in box2:
        L -= need
        if L < 0:
            print("No")
            return
        L += surplus

    print("Yes" if L == R else "No")

if __name__ == "__main__":
    main()

