import sys

readline = sys.stdin.buffer.readline

def check(arr):
    h = 0
    for b, d in arr:
        if h + b < 0:
            return False
        h += d
    return True

def main():
    n = int(readline())
    ls = []
    rs = []
    total = 0
    bm = 0

    for _ in range(n):
        s = readline().strip().decode()
        b = 0
        h = 0
        for c in s:
            if c == '(':
                h += 1
            else:
                h -= 1
                if h < b:
                    b = h

        if h == 0:
            if b != 0:
                bm = min(bm, b)
        elif h > 0:
            ls.append((b, h))
        else:
            rs.append((b - h, -h))
        total += h

    ls.append((bm, 0))

    if total != 0:
        print("No")
        return

    ls.sort(key=lambda x: x[0], reverse=True)
    if not check(ls):
        print("No")
        return

    rs.sort(key=lambda x: x[0], reverse=True)
    if not check(rs):
        print("No")
        return

    print("Yes")

if __name__ == "__main__":
    main()

