import sys
from heapq import heappush, heappop

input = sys.stdin.readline

N = int(input())
pos = []
zero = []
neg = []

for _ in range(N):
    s = input().rstrip()
    sm = 0
    mn = 0
    for c in s:
        if c == '(':
            sm += 1
        else:
            sm -= 1
            if sm < mn:
                mn = sm

    if sm > 0:
        heappush(pos, (-mn, sm))   # larger minimum first
    elif sm == 0:
        heappush(zero, (mn, sm))
    else:
        heappush(neg, (mn - sm, sm))  # smaller effective minimum first

hp = 0
while pos:
    m, s = heappop(pos)
    if hp - m < 0:
        print('No')
        sys.exit()
    hp += s

while zero:
    m, s = heappop(zero)
    if hp + m < 0:
        print('No')
        sys.exit()

while neg:
    m, s = heappop(neg)
    m += s
    if hp + m < 0:
        print('No')
        sys.exit()
    hp += s

print('Yes' if hp == 0 else 'No')

