import sys

def input():
    return sys.stdin.readline().strip()

def main():
    n = int(input())
    A = []
    B = []

    for _ in range(n):
        s = input()
        tmp = []
        for ch in s:
            if ch == '(':
                tmp.append(ch)
            else:
                if tmp and tmp[-1] == '(':
                    tmp.pop()
                else:
                    tmp.append(ch)

        l = tmp.count('(')
        r = len(tmp) - l

        if r - l <= 0:
            A.append((l, r))
        else:
            B.append((l, r))

    A.sort(key=lambda x: x[1])
    B.sort(key=lambda x: x[0], reverse=True)

    cur = 0
    for l, r in A:
        cur += r
        if cur > 0:
            print("No")
            return
        cur -= l

    for l, r in B:
        cur += r
        if cur > 0:
            print("No")
            return
        cur -= l

    print("Yes" if cur == 0 else "No")

if __name__ == "__main__":
    main()

