#!/usr/bin/env python
# -*- coding: utf-8 -*-

import sys

def main():
    input = sys.stdin.readline
    N = int(input())

    pos = []
    neg = []
    total = 0
    min_zero = 0

    for _ in range(N):
        s = input().strip()
        h = 0
        b = 0
        for c in s:
            if c == '(':
                h += 1
            else:
                h -= 1
            if h < b:
                b = h

        total += h
        if h == 0:
            if b != 0:
                if b < min_zero:
                    min_zero = b
        elif h > 0:
            pos.append((b, h))
        else:
            neg.append((b - h, -h))

    if total != 0:
        print("No")
        return

    pos.append((min_zero, 0))

    def check(arr):
        h = 0
        for need, add in arr:
            if h + need < 0:
                return False
            h += add
        return True

    pos.sort(key=lambda x: x[0], reverse=True)
    if not check(pos):
        print("No")
        return

    neg.sort(key=lambda x: x[0], reverse=True)
    if not check(neg):
        print("No")
        return

    print("Yes")

if __name__ == '__main__':
    main()

