import sys

def input():
    return sys.stdin.buffer.readline().decode().strip()

N = int(input())

A = []
B = []

for _ in range(N):
    S = input()
    bal = 0
    min_bal = 0
    for c in S:
        if c == '(':
            bal += 1
        else:
            bal -= 1
        if bal < min_bal:
            min_bal = bal

