patch:
from sys import stdin

def main():
    readline = stdin.readline
    n = int(readline())
    s = [readline().strip() for _ in range(n)]

    plus, minus = [], []
    for c in s:
        ts = 0
        min_s = 0
        for char in c:
            ts += 1 if char == '(' else -1
            min_s = min(min_s, ts)
        if ts >= 0:
            plus.append((-min_s, ts))
        else:
            minus.append((-(min_s - ts), -ts))

    plus.sort()
    minus.sort()

    s1 = 0
    for m, t in plus:
        if s1 - m < 0:
            return print('No')
        s1 += t

    s2 = 0
    for m, t in minus:
        if s2 - m < 0:
            return print('No')
        s2 += t

    if s1 == s2:
        return print('Yes')
    else:
        return print('No')

if __name__ == '__main__':
    main()

