    for i in range(n):
        p = 0
        m = 0
        for j in a[i]:
            if j == "(":
                p += 1
            else:
                p -= 1
            if p < m:
                m = p
        if p > 0:
            sp.append((m,p))
        else:
            sm.append((m,p))
    sp.sort(reverse = True)
    sm.sort(key = lambda x:x[0]-x[1])
    k = 0
