    S_down = []
    for _ in range(N):
        s = input()
        max_depth = 0
        height = 0
        for c in s:
            if c == '(':
                height += 1
            else:
                height -= 1
                max_depth = min(max_depth, height)
        if height > 0: S_up.append((max_depth, height - max_depth))
        else: S_down.append((-(height - max_depth), -max_depth))
    S_up.sort(key=lambda x: (x[0], x[1]))
    S_down.sort(key=lambda x: (x[0], x[1]))

    height_left = 0
    while S_up:
        d, h = S_up.pop()
        if height_left + d < 0:
            print("No")
            return
        height_left += d+h

    height_right = 0
    while S_down:
        d, h = S_down.pop()
        if height_right + d < 0:
            print("No")
            return
        height_right += d+h

    if height_left != height_right: print("No")
    else: print("Yes")

if __name__ == "__main__":
    main()

