def main():
    n = int(input())
    s = [input() for _ in range(n)]
    left = []
    mid = []
    midminus = []
    right = []
    L = []
    R = []

    for i in range(n):
        l = 0
        r = 0
        for x in s[i]:
            if x == '(':
                l += 1
            else:
                if l > 0:
                    l -= 1
                else:
                    r += 1
        if l > 0 and r == 0:
            left.append((l, r))
        elif l > 0 and r > 0:
            if l > r:
                mid.append((r, l))  # a,b-a
            else:
                midminus.append((r,l))
        elif l == 0 and r > 0:
            right.append((l, r))
        L.append(l)
        R.append(r)

    if sum(L) != sum(R):
        print('No')
        return

    A = 0
    B = 0
    for x in left:
        A += x[0]
    for x in right:
        B += x[1]

    mid = sorted(mid, key=lambda x: (x[0],-x[1]))
    midminus = sorted(midminus,key= lambda x:x[0]-x[1])
    mid += midminus

    l = A
    r = 0
    for a, b in mid:
        if l < a:
            print('No')
            return
        l -= a
        l += b

    print('Yes')

if __name__ == "__main__":
    main()

